SELECT id, sku_id, sku_code, sku_name, spec_text, order_item_id, stock_order_id,
       type, reason, qty, balance_after, operator_id, operator_name, remark, create_time
FROM stock_transaction

    AND sku_id = #{skuId}
    AND type = #{type}
    AND reason = #{reason}
    AND order_item_id = #{orderItemId}
    AND create_time >= #{startTime}
    AND create_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)

ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM stock_transaction

    AND sku_id = #{skuId}
    AND type = #{type}
    AND reason = #{reason}
    AND order_item_id = #{orderItemId}
    AND create_time >= #{startTime}
    AND create_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
